<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {get,request} from '../api/client'
const rows=ref<any[]>([]),form=ref<any>(null),error=ref(''),busy=ref(false)
async function load(){rows.value=await get('/api/v1/admin/content-types')}
function open(row?:any){form.value=row?{...row}:{code:'',name:'',renderer:'TEXT',requireOriginal:false,requireBody:true,requireSummary:false,requireImage:false,requireDates:false,enabled:true,lockVersion:0}}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await request('PUT','/api/v1/admin/content-types/'+form.value.code,form.value);form.value=null;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>load().catch(e=>error.value=e.message))
</script><template><section><div class="title-row"><h1>信息类型</h1><button @click="open()">新增类型</button></div><p>已支持的渲染器可配置必填字段；全新交互仍需研发。修改规则影响之后的创建与修正。</p><p class="error" role="alert">{{ error }}</p><div class="panel"><table><thead><tr><th>编码</th><th>名称</th><th>渲染</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.code"><td>{{ r.code }}</td><td>{{ r.name }}</td><td>{{ r.renderer }}</td><td>{{ r.enabled?'启用':'停用' }}</td><td><button class="quiet" @click="open(r)">编辑</button></td></tr></tbody></table></div><div v-if="form" class="overlay"><form class="dialog" @submit.prevent="save"><label>编码<input v-model="form.code" required pattern="[A-Z][A-Z0-9_]{0,19}" :disabled="form.lockVersion>0||rows.some(r=>r.code===form.code)"/></label><label>名称<input v-model="form.name" required maxlength="100"/></label><label>渲染方式<select v-model="form.renderer"><option>TEXT</option><option>NOTICE</option><option>LONG_IMAGE</option></select></label><label v-for="(label,key) in {requireOriginal:'原文必填',requireBody:'正文必填',requireSummary:'一句话必填',requireImage:'长图必填',requireDates:'起止时间必填',enabled:'启用'}" :key="key"><input v-model="form[key]" type="checkbox"/>{{ label }}</label><p class="error">{{ error }}</p><button :disabled="busy">保存</button><button type="button" class="quiet" @click="form=null">取消</button></form></div></section></template>
